import { readFile, writeFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';

const root = fileURLToPath(new URL('../', import.meta.url));
const repo = fileURLToPath(new URL('../../', import.meta.url));
const sources = [
  'src/15-viewmodels.ts',
  'src/15a-optics-prism.ts',
  'src/15b-optics-holo.ts',
  'src/16-viewmodels-b.ts',
  'src/16a-viewmodel-ak.ts',
  'src/16b-viewmodels-smg.ts',
];

const prefix = `// @ts-nocheck
/* GENERATED by scripts/generate-viewmodels.mjs from the legacy single-player
   viewmodel sources. Modeling is intentionally NOT re-authored. */
import * as THREE from 'three';

const MAXANISO = 8;
const PI = Math.PI;
const clamp = THREE.MathUtils.clamp;
const lerp = THREE.MathUtils.lerp;
const rand = (a, b) => a + Math.random() * (b - a);
const randI = (a, b) => Math.floor(rand(a, b + 1));
const pick = (a) => a[(Math.random() * a.length) | 0];
const damp = (cur, tgt, lambda, dt) => lerp(cur, tgt, 1 - Math.exp(-lambda * dt));
const easeOutCubic = (t) => 1 - (1 - t) ** 3;
const easeInOutCubic = (t) => (t < 0.5 ? 4 * t * t * t : 1 - (-2 * t + 2) ** 3 / 2);

function linearizeMats(dict) {
  for (const k in dict) {
    const m = dict[k];
    if (!m) continue;
    if (m.color && m.color.convertSRGBToLinear) m.color.convertSRGBToLinear();
    if (m.emissive && m.emissive.convertSRGBToLinear) m.emissive.convertSRGBToLinear();
  }
  return dict;
}

function cvs(size) {
  const c = document.createElement('canvas');
  c.width = c.height = size;
  return [c, c.getContext('2d')];
}

function finishTex(c, rep, srgb = true) {
  const t = new THREE.CanvasTexture(c);
  t.wrapS = t.wrapT = THREE.RepeatWrapping;
  if (rep) t.repeat.set(rep[0], rep[1]);
  t.anisotropy = MAXANISO;
  if (srgb) t.colorSpace = THREE.SRGBColorSpace;
  return t;
}

function grain(ctx, size, amt) {
  const img = ctx.getImageData(0, 0, size, size);
  const d = img.data;
  for (let i = 0; i < d.length; i += 4) {
    const n = (Math.random() - 0.5) * amt;
    d[i] = clamp(d[i] + n, 0, 255);
    d[i + 1] = clamp(d[i + 1] + n, 0, 255);
    d[i + 2] = clamp(d[i + 2] + n, 0, 255);
  }
  ctx.putImageData(img, 0, 0);
}

function splotches(ctx, size, n, colors, rMin, rMax, alpha) {
  for (let i = 0; i < n; i++) {
    const x = Math.random() * size;
    const y = Math.random() * size;
    const r = rand(rMin, rMax);
    const g = ctx.createRadialGradient(x, y, 0, x, y, r);
    const col = pick(colors);
    g.addColorStop(0, \`rgba(\${col},\${alpha})\`);
    g.addColorStop(1, \`rgba(\${col},0)\`);
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.arc(x, y, r, 0, 7);
    ctx.fill();
  }
}

function makeGlowTex() {
  const S = 128;
  const [c, x] = cvs(S);
  const g = x.createRadialGradient(S / 2, S / 2, 0, S / 2, S / 2, S / 2);
  g.addColorStop(0, 'rgba(255,255,255,1)');
  g.addColorStop(0.22, 'rgba(255,236,180,.95)');
  g.addColorStop(0.5, 'rgba(255,150,40,.45)');
  g.addColorStop(1, 'rgba(255,90,0,0)');
  x.fillStyle = g;
  x.fillRect(0, 0, S, S);
  const t = new THREE.CanvasTexture(c);
  t.colorSpace = THREE.SRGBColorSpace;
  return t;
}

const TEX = { glow: makeGlowTex() };

/* The legacy prism scope samples the main render target. Campaign owns a
   different pipeline, so bridge it to a neutral texture; the exact world
   texture will be wired when the post chain is unified. */
const _bridgeCanvas = document.createElement('canvas');
_bridgeCanvas.width = _bridgeCanvas.height = 4;
const worldRT = { texture: new THREE.CanvasTexture(_bridgeCanvas) };
const RTW = window.innerWidth;
const RTH = window.innerHeight;
const allocTargets = { onPrismResize: [] };
const PRISM_MAGNIFICATION = 2.5;

`;

let body = '';
for (const file of sources) {
  let text = await readFile(new URL(`../../${file}`, import.meta.url), 'utf-8');
  text = text.replace(/\/\/ @ts-nocheck[^\n]*\n?/, '').replace(/'use strict';?\s*\n?/, '');
  body += `\n/* ==== ${file} ==== */\n${text}\n`;
}

const suffix = `
export {
  buildRifle,
  buildShotgun,
  buildPistol,
  buildSniper,
  buildLMG,
  buildModernAK,
  buildVector,
  buildP90,
  buildJugGatling,
};
`;

await writeFile(new URL('../src/generated-viewmodels.ts', import.meta.url), prefix + body + suffix);
console.log(`wrote ${root}src/generated-viewmodels.ts`);
